/*
  src/components/PaperCard.jsx
  -----------------------------
  One research paper card. Day 5 redesign.

  Key improvements:
    - Decorative card number (large italic numeral)
    - Better badge system (arxiv vs semantic scholar)
    - Gold accent bar on hover (::before pseudo-element in CSS)
    - Smoother abstract expand/collapse
    - Better typography hierarchy
*/

import React, { useState } from 'react';
import { summarizePaper } from '../services/api';

function PaperCard({ paper, index }) {

  const [expanded, setExpanded]             = useState(false);
  const [summaryLoading, setSummaryLoading] = useState(false);
  const [onDemandSummary, setOnDemandSummary] = useState(null);

  const handleSummarize = async () => {
    if (!paper.abstract) return;
    setSummaryLoading(true);
    try {
      const result = await summarizePaper(paper.abstract);
      setOnDemandSummary(result.summary);
    } catch {
      setOnDemandSummary('Could not generate summary. Check your HuggingFace token in .env');
    } finally {
      setSummaryLoading(false);
    }
  };

  const displaySummary = onDemandSummary || paper.ai_summary;
  const shortAbstract  = paper.abstract
    ? paper.abstract.slice(0, 240) + (paper.abstract.length > 240 ? '…' : '')
    : null;

  /*
    formatAuthors: shows up to 3 names then "+N more"
    This keeps the card compact while crediting main authors.
  */
  const formatAuthors = (authors) => {
    if (!authors?.length) return 'Unknown authors';
    if (authors.length <= 3) return authors.join(', ');
    return `${authors.slice(0, 3).join(', ')} +${authors.length - 3} more`;
  };

  /*
    toLocaleString() adds thousands separators:
    1842 → "1,842"  |  50000 → "50,000"
    Locale-aware: Indian locale shows "1,84,200" etc.
  */
  const formatCitations = (n) =>
    n > 0 ? `⭐ ${n.toLocaleString()}` : null;

  return (
    <div
      className="paper-card"
      style={{ animationDelay: `${index * 0.055}s` }}
      /*
        animationDelay staggers card entrance:
        Card 0 → 0s delay (appears first)
        Card 1 → 0.055s delay
        Card 2 → 0.11s delay
        Creates a cascading wave effect
      */
    >
      {/* Decorative background number */}
      <span className="card-number" aria-hidden="true">
        {String(index + 1).padStart(2, '0')}
      </span>

      {/* ── Top section ── */}
      <div className="card-top">

        {/* Badges row */}
        <div className="card-badges">
          <span className={paper.source === 'semantic_scholar' ? 'badge badge-ss' : 'badge badge-arxiv'}>
            {paper.source === 'semantic_scholar' ? 'Semantic Scholar' : 'arXiv'}
          </span>
          {paper.year && (
            <span className="badge badge-year">{paper.year}</span>
          )}
          {paper.citation_count > 0 && (
            <span className="badge badge-cite">
              {formatCitations(paper.citation_count)}
            </span>
          )}
        </div>

        {/* Title */}
        {paper.url ? (
          <a
            href={paper.url}
            target="_blank"
            rel="noopener noreferrer"
            /*
              rel="noopener noreferrer" is a security best practice.
              Without it, the new tab can access window.opener and
              potentially redirect the original tab.
            */
            className="card-title"
          >
            {paper.title}
          </a>
        ) : (
          <span className="card-title">{paper.title}</span>
        )}

        {/* Authors */}
        <p className="card-authors">
          <span className="authors-icon">👤</span>
          {formatAuthors(paper.authors)}
        </p>

      </div>

      {/* ── AI Summary ── */}
      {displaySummary && (
        <div className="summary-block">
          <div className="summary-header">
            <span className="summary-label">🤖 AI Summary</span>
            {displaySummary.startsWith('[Extracted]') && (
              <span className="summary-tag-extracted">extracted</span>
            )}
          </div>
          <p className="summary-text">
            {displaySummary.replace('[Extracted] ', '')}
          </p>
        </div>
      )}

      {/* ── Abstract ── */}
      {paper.abstract && (
        <div className="abstract-block">
          <div className="abstract-label">Abstract</div>
          <p className="abstract-text">
            {expanded ? paper.abstract : shortAbstract}
          </p>
          {paper.abstract.length > 240 && (
            <button
              className="abstract-toggle"
              onClick={() => setExpanded(!expanded)}
            >
              {expanded ? '▲ Show less' : '▼ Read more'}
            </button>
          )}
        </div>
      )}

      {/* ── Footer ── */}
      <div className="card-footer">

        {!displaySummary && paper.abstract && (
          <button
            className="btn-summarize"
            onClick={handleSummarize}
            disabled={summaryLoading}
          >
            {summaryLoading
              ? <><span className="btn-mini-spin"></span> Generating…</>
              : '✨ Generate Summary'
            }
          </button>
        )}

        {paper.url && (
          <a
            href={paper.url}
            target="_blank"
            rel="noopener noreferrer"
            className="btn-read"
          >
            Read paper →
          </a>
        )}

      </div>
    </div>
  );
}

export default PaperCard;
